example:
composition "Silence" { ample 1  tempo 96  master-seed 81 }

midi-clip phrase {
  chords C Am F G
  bars 4
}

synth source {
  wave triangle
  gain -9 dB
  from phrase.notes -> notes
}

silence gap {
  length 2 s
}

mixer room {
  inputs 4
  from source.audio -> audio1
  from gap.audio -> audio2
}

master output {
  from room.audio -> audio
}
